# Generated by manage.py generate_test_cases.
import json

from bloomerp.models.workspaces.tile import Tile
from bloomerp.tests.base import (
    BloomerpAPIDetailViewTestCase,
    ExpectedResult,
    RequestScenario,
    ModelRequestScenario,
)
from bloomerp.workspaces.tiles import TileType


class TestSaveCanvasStateView(BloomerpAPIDetailViewTestCase):
    """Tests function `save_canvas_state` from `bloomerp/views/api/workspaces/tile.py`."""

    view_name = 'api_tile_canvas_state'
    model = Tile

    def get_test_scenarios(self) -> list[RequestScenario]:
        return [
            RequestScenario(
                name="Canvas owner can save state",
                description=(
                    "UC: A user changes a canvas tile they created.\n"
                    "Expected Result: The state is saved without losing the canvas height."
                ),
                method="POST",
                user=self.normal_user,
                content_type="application/json",
                prepare=lambda scenario: self.prepare_tile(
                    scenario,
                    owner=self.normal_user,
                    tile_type=TileType.CANVAS_TILE.name,
                    state={"elements": [{"id": "shape-1"}]},
                ),
                expected=ExpectedResult(
                    response_validators=self.canvas_state_was_saved,
                ),
            ),
            RequestScenario(
                name="Authenticated staff user can save a shared canvas",
                description=(
                    "UC: A staff user edits a canvas created by another user.\n"
                    "Expected Result: The current low-risk canvas policy accepts and records the write."
                ),
                method="POST",
                user=self.normal_user,
                content_type="application/json",
                prepare=lambda scenario: self.prepare_tile(
                    scenario,
                    owner=self.admin_user,
                    tile_type=TileType.CANVAS_TILE.name,
                    state={"elements": [{"id": "blocked"}]},
                ),
                expected=ExpectedResult(response_validators=self.canvas_state_was_saved),
            ),
            RequestScenario(
                name="Non-canvas tile rejects canvas state",
                description=(
                    "UC: Canvas state is posted to a different tile type.\n"
                    "Expected Result: The endpoint returns 400 and preserves its schema."
                ),
                method="POST",
                user=self.normal_user,
                content_type="application/json",
                prepare=lambda scenario: self.prepare_tile(
                    scenario,
                    owner=self.normal_user,
                    tile_type=TileType.TEXT_TILE.name,
                    state={"elements": []},
                    schema={"markdown": "Keep me"},
                ),
                expected=ExpectedResult(
                    status_code=400,
                    response_validators=self.tile_schema_is_unchanged,
                ),
            ),
            RequestScenario(
                name="Canvas state must be an object",
                description=(
                    "UC: A canvas update contains a non-object state.\n"
                    "Expected Result: The endpoint returns 400 and leaves the canvas unchanged."
                ),
                method="POST",
                user=self.normal_user,
                content_type="application/json",
                prepare=lambda scenario: self.prepare_tile(
                    scenario,
                    owner=self.normal_user,
                    tile_type=TileType.CANVAS_TILE.name,
                    state=[],
                ),
                expected=ExpectedResult(
                    status_code=400,
                    response_validators=self.tile_schema_is_unchanged,
                ),
            ),
        ]

    def prepare_tile(self, scenario, *, owner, tile_type, state, schema=None):
        self.tile = Tile.objects.create(
            name="Canvas scenario",
            description="",
            type=tile_type,
            schema=schema or {"content": {}, "height": 480},
            created_by=owner,
            updated_by=owner,
        )
        self.original_schema = self.tile.schema.copy()
        self.expected_state = state
        scenario.view_kwargs = {"pk": self.tile.pk}
        scenario.data = json.dumps({"state": state})

    def canvas_state_was_saved(self, _response):
        self.tile.refresh_from_db()
        return (
            self.tile.schema["content"] == self.expected_state
            and self.tile.schema["height"] == 480
            and self.tile.updated_by == self.normal_user
        )

    def tile_schema_is_unchanged(self, _response):
        self.tile.refresh_from_db()
        return self.tile.schema == self.original_schema
